function validate([s]) {
  if (typeof s !== 'string' || s.length < 2 || s.length > 200) return 's needs 2 to 200 characters.';
  const words = s.split(' ');
  if (words.length > 9) return 's has at most 9 words.';
  if (words.some(w => !/^[A-Za-z]+[1-9]$/.test(w))) return 'Each word is letters followed by one digit, separated by single spaces.';
  const positions = words.map(w => Number(w[w.length - 1])).sort((a, b) => a - b);
  if (positions.some((p, i) => p !== i + 1)) return 'The digits must number the words 1 to k exactly once.';
  return null;
}

