function sortSentence(s) {
  const words = s.split(' ');
  const ordered = new Array(words.length);
  for (const word of words) {
    const position = Number(word[word.length - 1]);
    ordered[position - 1] = word.slice(0, -1);
  }
  return ordered.join(' ');
}

