function sortSentence(s) {
  const tagged = s.split(' ');
  tagged.sort((a, b) => a.charCodeAt(a.length - 1) - b.charCodeAt(b.length - 1));
  return tagged.map(word => word.replace(/[1-9]$/, '')).join(' ');
}

