function generate(rand, size) {
  const letters = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ';
  const count = size === 'large' ? 9 : 1 + Math.floor(rand() * 9);
  const longest = size === 'large' ? 20 : 1 + Math.floor(rand() * 4);
  const words = [];
  for (let k = 1; k <= count; k++) {
    const length = size === 'large' ? 12 + Math.floor(rand() * 9) : 1 + Math.floor(rand() * longest);
    let word = '';
    for (let c = 0; c < length; c++) word += letters[Math.floor(rand() * letters.length)];
    words.push(word + k);
  }
  for (let i = words.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [words[i], words[j]] = [words[j], words[i]];
  }
  return [words.join(' ')];
}
